If your code touches registers, it is "welded" to the hardware. Use function pointers to break the connection for testing. // temp_sensor.h
typedef struct { uint16_t (*read_reg)(uint8_t addr);
} i2c_ops_t; // The logic under test
uint16_t get_temperature(i2c_ops_t *ops) { return ops->read_reg(0x05); } // In your Test
uint16_t mock_read(uint8_t addr) { return 0x00FF; // Controlled test value
} void test_temp(void) { i2c_ops_t mock_ops = { .read_reg = mock_read }; assert(get_temperature(&mock_ops) == 255);
} By passing a "dictionary" of operations, you can verify your algorithm's response to any hardware state without physical silicon.

